    red: { bg: 'from-red-500/10 to-red-600/5', border: 'border-red-500/20', text: 'text-red-400' },
    purple: { bg: 'from-purple-500/10 to-purple-600/5', border: 'border-purple-500/20', text: 'text-purple-400' }
