// src/config/routes.config.tsx
// AI DASHBOARD ROUTE CONFIGURATION
import React, { lazy } from 'react';
import {
  MessageCircle, BarChart3, TrendingUp, Workflow, Users,
  BookOpen, GraduationCap, Settings, Baby, Heart,
  Stethoscope, Sparkles
} from 'lucide-react';
import PlaceholderPage from '../components/common/PlaceholderPage';

// ============================================
// TYPES
// ============================================
export interface AIDashboardRoute {
  path: string;
  label: string;
  icon: React.ElementType;
  color?: string;
  description?: string;
  isSidebar?: boolean;
  isFeature?: boolean;
}

// ============================================
// SIDEBAR ROUTES (Main navigation)
// ============================================
export const sidebarRoutes: AIDashboardRoute[] = [
  { path: 'chat', label: 'AI Chat', icon: MessageCircle, color: 'purple', description: 'Chat with AI assistant', isSidebar: true },
  { path: 'analytics', label: 'Analytics', icon: BarChart3, color: 'cyan', description: 'View AI system analytics', isSidebar: true },
  { path: 'predictions', label: 'Predictions', icon: TrendingUp, color: 'amber', description: 'AI predictions & forecasts', isSidebar: true },
  { path: 'automation', label: 'Automation', icon: Workflow, color: 'emerald', description: 'Automation rules', isSidebar: true },
  { path: 'agents', label: 'Agents', icon: Users, color: 'blue', description: 'AI agent management', isSidebar: true },
  { path: 'knowledge', label: 'Knowledge Base', icon: BookOpen, color: 'indigo', description: 'AI knowledge base', isSidebar: true },
  { path: 'training', label: 'Training', icon: GraduationCap, color: 'pink', description: 'Model training', isSidebar: true },
  { path: 'settings', label: 'Settings', icon: Settings, color: 'slate', description: 'AI system settings', isSidebar: true },
];

// ============================================
// FEATURE ROUTES (Quick access cards)
// ============================================
export const featureRoutes: AIDashboardRoute[] = [
  { path: 'baby-care', label: 'Baby Care', icon: Baby, color: 'rose', description: 'AI baby care advice', isFeature: true },
  { path: 'pregnancy', label: 'Pregnancy Guide', icon: Heart, color: 'pink', description: 'AI pregnancy guidance', isFeature: true },
  { path: 'symptoms', label: 'Symptom Checker', icon: Stethoscope, color: 'emerald', description: 'AI symptom analysis', isFeature: true },
  { path: 'recommendations', label: 'Recommendations', icon: Sparkles, color: 'amber', description: 'Smart recommendations', isFeature: true },
];

// ============================================
// ALL DASHBOARD ROUTES (Combined)
// ============================================
export const allDashboardRoutes: AIDashboardRoute[] = [
  ...sidebarRoutes,
  ...featureRoutes,
];

// ============================================
// LAZY LOADED COMPONENT MAP
// ============================================
export interface RouteComponentMap {
  [key: string]: React.LazyExoticComponent<React.ComponentType<Record<string, never>>>;
}

/**
 * Helper to create a lazy component with error fallback
 */
const createLazyComponent = (importFn: () => Promise<unknown>, title: string) => {
  return lazy(() =>
    (importFn() as Promise<{ default: React.ComponentType<Record<string, never>> }>).catch(() => ({
      default: () => <PlaceholderPage title={title} />
    }))
  );
};

// Lazy-loaded route components
export const routeComponents: RouteComponentMap = {
  'chat': createLazyComponent(
    () => import('../components/ai-assistent/AIAssistantWidget'),
    'AI Chat'
  ),
  'analytics': createLazyComponent(
    () => import('../components/dashboard/Activitychart'),
    'Analytics'
  ),
  'predictions': createLazyComponent(
    () => import('../components/ai-assistent/AIResponseCard'),
    'Predictions'
  ),
  'automation': createLazyComponent(
    () => import('../components/ai-assistent/AISuggestionChips'),
    'Automation'
  ),
  'agents': createLazyComponent(
    () => import('../components/ai-assistent/AIVoiceButton'),
    'AI Agents'
  ),
  'knowledge': createLazyComponent(
    () => import('../components/ai-assistent/AIAssistant'),
    'Knowledge Base'
  ),
  'training': createLazyComponent(
    () => import('../components/ai-assistent/AIVoiceButton'),
    'Training'
  ),
  'settings': createLazyComponent(
    () => import('../components/ai-assistent/AIAssistant'),
    'Settings'
  ),
  'baby-care': createLazyComponent(
    () => import('../components/ai-assistent/BabyCareAdvice').then(m => ({ default: m.BabyCareAdvice })),
    'Baby Care'
  ),
  'pregnancy': createLazyComponent(
    () => import('../components/ai-assistent/PregnancyGuide').then(m => ({ default: m.PregnancyGuide })),
    'Pregnancy Guide'
  ),
  'symptoms': createLazyComponent(
    () => import('../components/ai-assistent/SymptomChecker').then(m => ({ default: m.SymptomChecker })),
    'Symptom Checker'
  ),
  'recommendations': createLazyComponent(
    () => import('../components/ai-assistent/SmartRecommendation'),
    'Recommendations'
  ),
};

// ============================================
// HELPER FUNCTIONS
// ============================================

/**
 * Get the default route (first sidebar route)
 */
export const getDefaultRoute = (): string => {
  return sidebarRoutes[0]?.path || 'chat';
};

/**
 * Get sidebar routes only
 */
export const getSidebarRoutes = (): AIDashboardRoute[] => sidebarRoutes;

/**
 * Get feature routes only
 */
export const getFeatureRoutes = (): AIDashboardRoute[] => featureRoutes;

/**
 * Get Tailwind color classes for a given color name
 */
export const getColorClasses = (color: string): string => {
  const colorMap: Record<string, string> = {
    blue: 'bg-blue-500/10 text-blue-400',
    teal: 'bg-teal-500/10 text-teal-400',
    purple: 'bg-purple-500/10 text-purple-400',
    amber: 'bg-amber-500/10 text-amber-400',
    green: 'bg-green-500/10 text-green-400',
    red: 'bg-red-500/10 text-red-400',
    cyan: 'bg-cyan-500/10 text-cyan-400',
    emerald: 'bg-emerald-500/10 text-emerald-400',
    indigo: 'bg-indigo-500/10 text-indigo-400',
    slate: 'bg-slate-500/10 text-slate-400',
    pink: 'bg-pink-500/10 text-pink-400',
    rose: 'bg-rose-500/10 text-rose-400',
  };
  return colorMap[color] || 'bg-purple-500/10 text-purple-400';
};

/**
 * Get a route by its path
 */
export const getRouteByPath = (path: string): AIDashboardRoute | undefined => {
  return allDashboardRoutes.find(r => r.path === path);
};

/**
 * Get the component for a given route path
 */
export const getRouteComponent = (path: string): React.LazyExoticComponent<React.ComponentType<Record<string, never>>> | null => {
  return routeComponents[path] || null;
};

// src/components/admin/EmergencyMonitor.tsx

import React, { useState, useEffect } from 'react';
import {
  Radio, AlertCircle, MapPin, Clock, Users,
  Phone, CheckCircle, XCircle, Truck, Droplet,
  Wind, Activity, RefreshCw
} from 'lucide-react';
import { EmergencyAlert } from '../../types/admin';

export const EmergencyMonitor: React.FC = () => {
  const [emergencies, setEmergencies] = useState<EmergencyAlert[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [autoRefresh, setAutoRefresh] = useState(true);

  useEffect(() => {
    fetchEmergencies();
    
    if (autoRefresh) {
      const interval = setInterval(fetchEmergencies, 30000); // Refresh every 30s
      return () => clearInterval(interval);
    }
    return undefined;
  }, [autoRefresh]);

  const fetchEmergencies = async () => {
    setIsLoading(true);
    setTimeout(() => {
      const mockEmergencies: EmergencyAlert[] = [
        {
          id: '1',
          type: 'blood',
          title: 'Emergency Blood Required',
          description: 'O-negative blood needed for emergency surgery',
          location: 'City General Hospital',
          coordinates: { latitude: 40.7128, longitude: -74.006 },
          severity: 'critical',
          status: 'active',
          reportedBy: 'Dr. Wilson',
          reportedDate: '2024-02-16T10:00:00',
          responders: [
            {
              id: 'r1',
              name: 'Blood Bank Unit 1',
              type: 'hospital',
              status: 'dispatched',
              estimatedArrival: '15 min',
              contactPhone: '+1 (555) 111-2222'
            }
          ],
          updates: [
            {
              id: 'u1',
              message: 'Emergency declared - Critical patient needs O- blood',
              timestamp: '2024-02-16T10:00:00',
              updatedBy: 'System'
            }
          ]
        }
      ];
      setEmergencies(mockEmergencies);
      setIsLoading(false);
    }, 1000);
  };

  const getTypeIcon = (type: string) => {
    switch(type) {
      case 'blood': return <Droplet className="w-6 h-6 text-red-500" />;
      case 'oxygen': return <Wind className="w-6 h-6 text-blue-500" />;
      case 'ambulance': return <Truck className="w-6 h-6 text-orange-500" />;
      case 'medical': return <Activity className="w-6 h-6 text-purple-500" />;
      default: return <AlertCircle className="w-6 h-6 text-yellow-500" />;
    }
  };

  const getSeverityColor = (severity: string) => {
    switch(severity) {
      case 'critical': return 'border-red-500 bg-red-50';
      case 'high': return 'border-orange-500 bg-orange-50';
      case 'medium': return 'border-yellow-500 bg-yellow-50';
      default: return 'border-blue-500 bg-blue-50';
    }
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center h-96">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-red-500"></div>
      </div>
    );
  }

  return (
    <div className="p-6">
      <div className="flex justify-between items-center mb-6">
        <div>
          <h1 className="text-2xl font-bold flex items-center">
            <Radio className="w-6 h-6 mr-2 text-red-500" />
            Emergency Monitor
          </h1>
          <p className="text-gray-600 mt-1">Real-time emergency response system</p>
        </div>
        <div className="flex items-center space-x-3">
          <label className="flex items-center space-x-2 text-sm">
            <input
              type="checkbox"
              checked={autoRefresh}
              onChange={(e) => setAutoRefresh(e.target.checked)}
              className="w-4 h-4"
            />
            <span>Auto-refresh (30s)</span>
          </label>
          <button
            onClick={fetchEmergencies}
            className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 flex items-center"
          >
            <RefreshCw className="w-4 h-4 mr-2" />
            Refresh Now
          </button>
        </div>
      </div>

      <div className="space-y-4">
        {emergencies.map((emergency) => (
          <div
            key={emergency.id}
            className={`bg-white rounded-lg shadow-lg border-l-4 ${getSeverityColor(emergency.severity)} p-6`}
          >
            <div className="flex items-start justify-between mb-4">
              <div className="flex items-start space-x-4">
                {getTypeIcon(emergency.type)}
                <div>
                  <h3 className="font-semibold text-lg">{emergency.title}</h3>
                  <p className="text-gray-600 mt-1">{emergency.description}</p>
                  <div className="flex items-center space-x-4 mt-2 text-sm text-gray-500">
                    <span className="flex items-center">
                      <MapPin className="w-4 h-4 mr-1" />
                      {emergency.location}
                    </span>
                    <span className="flex items-center">
                      <Clock className="w-4 h-4 mr-1" />
                      {new Date(emergency.reportedDate).toLocaleString()}
                    </span>
                    <span className="flex items-center">
                      <Users className="w-4 h-4 mr-1" />
                      {emergency.responders.length} responder(s)
                    </span>
                  </div>
                </div>
              </div>
              <div className="flex items-center space-x-2">
                <span className={`px-3 py-1 rounded-full text-sm font-medium ${
                  emergency.status === 'active' ? 'bg-red-100 text-red-700' :
                  emergency.status === 'responding' ? 'bg-yellow-100 text-yellow-700' :
                  'bg-green-100 text-green-700'
                }`}>
                  {emergency.status.toUpperCase()}
                </span>
                <span className={`px-3 py-1 rounded-full text-sm font-medium ${
                  emergency.severity === 'critical' ? 'bg-red-100 text-red-700' :
                  emergency.severity === 'high' ? 'bg-orange-100 text-orange-700' :
                  'bg-yellow-100 text-yellow-700'
                }`}>
                  {emergency.severity.toUpperCase()}
                </span>
              </div>
            </div>

            {/* Responders */}
            {emergency.responders.length > 0 && (
              <div className="mt-4">
                <h4 className="font-medium mb-2">Responders</h4>
                <div className="space-y-2">
                  {emergency.responders.map((responder) => (
                    <div key={responder.id} className="flex items-center justify-between bg-gray-50 p-3 rounded-lg">
                      <div className="flex items-center space-x-3">
                        <div className="w-8 h-8 bg-blue-100 rounded-full flex items-center justify-center">
                          <Truck className="w-4 h-4 text-blue-600" />
                        </div>
                        <div>
                          <p className="font-medium text-sm">{responder.name}</p>
                          <p className="text-xs text-gray-500 capitalize">{responder.type}</p>
                        </div>
                      </div>
                      <div className="flex items-center space-x-4">
                        <span className={`text-xs px-2 py-1 rounded-full ${
                          responder.status === 'dispatched' ? 'bg-yellow-100 text-yellow-700' :
                          responder.status === 'arrived' ? 'bg-green-100 text-green-700' :
                          'bg-blue-100 text-blue-700'
                        }`}>
                          {responder.status}
                        </span>
                        <span className="text-xs text-gray-500">ETA: {responder.estimatedArrival}</span>
                        <button className="text-blue-600 hover:text-blue-700">
                          <Phone className="w-4 h-4" />
                        </button>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            )}

            {/* Updates Timeline */}
            {emergency.updates.length > 0 && (
              <div className="mt-4">
                <h4 className="font-medium mb-2">Updates</h4>
                <div className="space-y-2">
                  {emergency.updates.map((update) => (
                    <div key={update.id} className="flex items-start space-x-2 text-sm">
                      <Activity className="w-4 h-4 text-blue-500 mt-0.5" />
                      <div>
                        <p>{update.message}</p>
                        <p className="text-xs text-gray-500">
                          {new Date(update.timestamp).toLocaleString()} by {update.updatedBy}
                        </p>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            )}

            {/* Actions */}
            <div className="mt-4 flex justify-end space-x-3">
              <button className="px-4 py-2 border border-gray-300 rounded-lg hover:bg-gray-50">
                Update Status
              </button>
              <button className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700">
                Dispatch Responder
              </button>
              {emergency.status !== 'resolved' && (
                <button className="px-4 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700">
                  Mark Resolved
                </button>
              )}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}
export default EmergencyMonitor;

import React, { useState } from 'react';
import { motion } from 'framer-motion';
import {
  MapPin,  AlertTriangle, TrendingUp, 
   Eye,  Thermometer,
} from 'lucide-react';
import {
  BarChart, Bar, XAxis, YAxis, CartesianGrid,
  Tooltip, ResponsiveContainer,
} from 'recharts';
import AdminSidebar from './AdminSidebar';
import { Card } from 'src/ui/Card';
import { GlassmorphicCard } from 'src/ui/GlassmorphicCard';
import { Button } from 'src/ui/Button';
import { Badge } from 'src/ui/Badge';

const areaDiseaseData = [
  { area: 'Dhaka', diabetes: 450, heart: 380, respiratory: 320, dengue: 290, cancer: 180 },
  { area: 'Chattogram', diabetes: 380, heart: 310, respiratory: 280, dengue: 420, cancer: 150 },
  { area: 'Sylhet', diabetes: 280, heart: 220, respiratory: 190, dengue: 150, cancer: 120 },
  { area: 'Rajshahi', diabetes: 320, heart: 280, respiratory: 250, dengue: 200, cancer: 140 },
  { area: 'Khulna', diabetes: 290, heart: 240, respiratory: 310, dengue: 350, cancer: 130 },
  { area: 'Barishal', diabetes: 200, heart: 180, respiratory: 220, dengue: 280, cancer: 90 },
  { area: 'Rangpur', diabetes: 180, heart: 160, respiratory: 200, dengue: 120, cancer: 80 },
  { area: 'Mymensingh', diabetes: 160, heart: 140, respiratory: 170, dengue: 190, cancer: 70 },
];

const healthAlerts = [
  { area: 'Chattogram', disease: 'Dengue', cases: 420, trend: 'up', severity: 'critical', status: 'outbreak' },
  { area: 'Dhaka', disease: 'Diabetes', cases: 450, trend: 'up', severity: 'high', status: 'endemic' },
  { area: 'Khulna', disease: 'Respiratory', cases: 310, trend: 'up', severity: 'high', status: 'warning' },
  { area: 'Sylhet', disease: 'Heart Disease', cases: 220, trend: 'stable', severity: 'medium', status: 'monitor' },
];

const HealthHeatmap: React.FC = () => {
  const [selectedDisease, setSelectedDisease] = useState('diabetes');

  const getHeatColor = (value: number) => {
    if (value > 380) return 'bg-red-500/30 border-red-500/50';
    if (value > 280) return 'bg-amber-500/20 border-amber-500/30';
    if (value > 180) return 'bg-yellow-500/10 border-yellow-500/20';
    return 'bg-emerald-500/10 border-emerald-500/20';
  };

  const getHeatIntensity = (value: number) => {
    if (value > 380) return 'text-red-400 font-black';
    if (value > 280) return 'text-amber-400 font-bold';
    if (value > 180) return 'text-yellow-400';
    return 'text-emerald-400';
  };

  return (
    <div className="min-h-screen bg-[#020408] flex">
      <AdminSidebar />
      <div className="flex-1 min-w-0">
        <div className="max-w-[1800px] mx-auto px-4 sm:px-6 lg:px-8 py-6 space-y-6">
          <motion.div initial={{ opacity: 0, y: -20 }} animate={{ opacity: 1, y: 0 }}>
            <div className="flex items-center justify-between mb-6">
              <div>
                <h1 className="text-2xl sm:text-3xl font-black text-white flex items-center gap-3">
                  <MapPin className="w-8 h-8 text-emerald-400" /> Health Heatmap
                </h1>
                <p className="text-slate-400 text-sm mt-1">Disease distribution & health analytics by area</p>
              </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 mb-6">
              <GlassmorphicCard className="p-6 lg:col-span-2">
                <div className="flex items-center justify-between mb-4">
                  <h3 className="text-white font-bold text-lg flex items-center gap-2">
                    <Thermometer className="w-5 h-5 text-emerald-400" /> Disease Heatmap by Division
                  </h3>
                  <div className="flex gap-1">
                    {['diabetes', 'heart', 'respiratory', 'dengue', 'cancer'].map(d => (
                      <Button key={d} variant={selectedDisease === d ? 'primary' : 'ghost'} size="xs"
                        onClick={() => setSelectedDisease(d)} className={selectedDisease === d ? 'bg-cyan-500' : 'text-slate-400'}>
                        {d.charAt(0).toUpperCase() + d.slice(1)}
                      </Button>
                    ))}
                  </div>
                </div>
                <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
                  {areaDiseaseData.map((area) => {
                    const value = area[selectedDisease as keyof typeof area] as number;
                    const color = getHeatColor(value);
                    const textColor = getHeatIntensity(value);
                    return (
                      <Card key={area.area} className={`p-4 border ${color} hover:shadow-lg transition-all`}>
                        <div className="flex items-center gap-2 mb-2">
                          <MapPin className="w-4 h-4 text-slate-400" />
                          <span className="text-white font-bold text-sm">{area.area}</span>
                        </div>
                        <p className={`text-2xl ${textColor}`}>{value}</p>
                        <p className="text-xs text-slate-400">Cases</p>
                        <div className="mt-2 h-1.5 bg-white/[0.06] rounded-full overflow-hidden">
                          <motion.div
                            initial={{ width: 0 }}
                            animate={{ width: `${(value / 500) * 100}%` }}
                            className={`h-full rounded-full ${
                              value > 380 ? 'bg-red-500' : value > 280 ? 'bg-amber-500' : value > 180 ? 'bg-yellow-500' : 'bg-emerald-500'
                            }`}
                          />
                        </div>
                      </Card>
                    );
                  })}
                </div>
              </GlassmorphicCard>

              <GlassmorphicCard className="p-6">
                <h3 className="text-white font-bold text-lg mb-4 flex items-center gap-2">
                  <AlertTriangle className="w-5 h-5 text-red-400" /> Health Alerts
                </h3>
                <div className="space-y-3">
                  {healthAlerts.map((alert, i) => (
                    <div key={i} className="p-3 rounded-2xl bg-white/[0.02] border border-white/[0.04]">
                      <div className="flex items-center justify-between">
                        <Badge variant={alert.severity === 'critical' ? 'danger' : alert.severity === 'high' ? 'warning' : 'info'} className="text-[10px]">{alert.severity}</Badge>
                        <Badge variant={alert.trend === 'up' ? 'danger' : 'info'} className="text-[10px]">{alert.trend}</Badge>
                      </div>
                      <h4 className="text-white font-bold text-sm mt-2">{alert.area}</h4>
                      <p className="text-xs text-slate-400">{alert.disease} • {alert.cases} cases</p>
                      <p className="text-xs text-slate-500 mt-1 capitalize">Status: {alert.status}</p>
                      <Button variant="primary" size="xs" className="w-full mt-2 bg-cyan-500"><Eye className="w-3 h-3 mr-1" /> View Details</Button>
                    </div>
                  ))}
                </div>
              </GlassmorphicCard>
            </div>

            <GlassmorphicCard className="p-6">
              <h3 className="text-white font-bold text-lg mb-4 flex items-center gap-2">
                <TrendingUp className="w-5 h-5 text-cyan-400" /> Disease Comparison by Area
              </h3>
              <ResponsiveContainer width="100%" height={350}>
                <BarChart data={areaDiseaseData}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#ffffff10" />
                  <XAxis dataKey="area" stroke="#ffffff40" />
                  <YAxis stroke="#ffffff40" />
                  <Tooltip contentStyle={{ backgroundColor: '#1a1a2e', border: '1px solid #ffffff20', borderRadius: '8px' }} />
                  <Bar dataKey="diabetes" fill="#3B82F6" radius={[4,4,0,0]} />
                  <Bar dataKey="heart" fill="#EF4444" radius={[4,4,0,0]} />
                  <Bar dataKey="respiratory" fill="#10B981" radius={[4,4,0,0]} />
                  <Bar dataKey="dengue" fill="#F59E0B" radius={[4,4,0,0]} />
                  <Bar dataKey="cancer" fill="#8B5CF6" radius={[4,4,0,0]} />
                </BarChart>
              </ResponsiveContainer>
            </GlassmorphicCard>
          </motion.div>
        </div>
      </div>
    </div>
  );
};

