                        <span className={`flex items-center text-xs ${stat.trend === 'up' ? 'text-emerald-400' : 'text-red-400'}`}>
                          {stat.trend === 'up' ? <ArrowUp className="w-3 h-3" /> : <ArrowDown className="w-3 h-3" />}
                          {stat.change}
                        </span>
                      </div>
                    </div>
                  ))}
                </div>
              </GlassmorphicCard>
            </div>
          </motion.div>
        </div>
      </div>
    </div>
  );
};

