                    leftIcon={Search}
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                  />
                </div>
                <div className="flex gap-2">
                  {['all', 'active', 'pending', 'suspended'].map(status => (
                    <Button
                      key={status}
